INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6001, 'Joshua 23:8', 'Joshua', 23, 8, '&nbsp;د دې په ځائ، د مالِک خُدائ هم هغه شان وفادار اوسئ، لکه څنګه چې تر اوسه پورې وفادار يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6002, 'Joshua 23:9', 'Joshua', 23, 9, '&nbsp;چې تاسو مخ په وړاندې تلئ نو مالِک خُدائ لوئ لوئ او تکړه قومونه شړلى دى او تر اوسه پورې څوک د دې قابل نۀ دى چې ستاسو خِلاف ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6003, 'Joshua 23:10', 'Joshua', 23, 10, '&nbsp;ستاسو هر يو کس زر سړو له منډه ورکولے شى، ځکه چې مالِک خُدائ ستاسو خُدائ پاک ستاسو دپاره جنګ کوى، هم هغه شان لکه څنګه چې هغۀ وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6004, 'Joshua 23:11', 'Joshua', 23, 11, '&nbsp;نو بيا کوشش کوئ چې د مالِک خُدائ خپل خُدائ پاک سره مينه وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6005, 'Joshua 23:12', 'Joshua', 23, 12, '&nbsp;کۀ تاسو بې‌وفا شئ او د هغه قومونو سره اِتحاد وکړئ کوم قومونه چې تر اوسه پورې ستاسو سره پاتې دى او د هغوئ سره ودونه وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6006, 'Joshua 23:13', 'Joshua', 23, 13, '&nbsp;نو تاسو يقين وکړئ چې کله تاسو مخ په وړاندې ځئ نو مالِک خُدائ ستاسو خُدائ پاک به نور هغه قومونه ونۀ شړى. او هغوئ به ستاسو دپاره د دام يا د کندې په شان خطرناک وى او د کوړې په شان به داسې دردناک وى لکه چې ستاسو ملا ورباندې ووهلے شى او يا چې ازغى ستاسو سترګې ړندې کړى. او دا به په هغه وخت ختم شى چې ستاسو يو کس هم په دې ښائسته مُلک کښې پاتې نۀ شى هغه مُلک چې مالِک خُدائ ستاسو خُدائ پاک تاسو له درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6007, 'Joshua 23:14', 'Joshua', 23, 14, '&nbsp;اوس زما د مرګ وخت نزدې دے او تاسو هر يو کس د زړۀ د کومې نه خبر يئ چې مالِک خُدائ ستاسو خُدائ پاک چې هره يوه وعده کړې ده نو هغه يې پوره کړې ده، داسې يوه وعده هم نشته چې پوره شوې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6008, 'Joshua 23:15', 'Joshua', 23, 15, '&nbsp;خو لکه څنګه چې هغۀ کومه وعده کړې ده او هره يوه يې پوره کړې ده، نو داسې کۀ تاسو د هغۀ نافرمانى وکړئ نو خُدائ پاک به هغه افتونه هم راولى. تاسو به تباه کړى او د هغه ښۀ مُلک نه به مو ورک کړى کوم ښۀ مُلک چې مالِک خُدائ ستاسو خُدائ پاک تاسو له درکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6009, 'Joshua 23:16', 'Joshua', 23, 16, '&nbsp;کۀ تاسو هغه لوظ مات کړئ چې مالِک خُدائ ستاسو خُدائ پاک د هغې سر ته رسولو حُکم درکړے دے او تاسو د نورو معبودانو خِدمت او عبادت وکړئ، نو بيا به هغه په خپله غصه کښې تاسو له سزا درکړى، نو ډېر زر به ستاسو يو کس هم په دې ښۀ مُلک کښې پاتې نۀ شى چې کوم هغۀ درکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6010, 'Joshua 24:1', 'Joshua', 24, 1, '&nbsp;يشوَع په شِکم کښې د بنى اِسرائيلو ټولې قبيلې راغونډې کړې. هغۀ مالِکان، مشران، قاضيان او د بنى اِسرائيلو آفسران راوغوښتل او هغوئ د خُدائ پاک حضور ته راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6011, 'Joshua 24:2', 'Joshua', 24, 2, '&nbsp;يشوَع خلقو ته وفرمائيل، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، ډېر وخت مخکښې، ستاسو پلار نيکۀ، سره د اِبراهيم او نحور د پلار تارح، د فرات سيند نه اخوا اوسېدل او هغوئ د نورو معبودانو عبادت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6012, 'Joshua 24:3', 'Joshua', 24, 3, '&nbsp;بيا ما ستاسو پلار نيکۀ اِبراهيم د فرات سيند نه اخوا مُلک نه روان کړو او د کنعان په ټول مُلک کښې مې وګرځولو. ما هغۀ له ډېر اولاد ورکړو. ما هغۀ له اِسحاق ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6013, 'Joshua 24:4', 'Joshua', 24, 4, '&nbsp;او اِسحاق له مې يعقوب او عِيسو ورکړل. ما عِيسو له د ادوم د غرونو مُلک ورکړو چې خپل ميراث يې شى، خو ستاسو پلار نيکۀ يعقوب او د هغۀ بچى لاندې مِصر ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6014, 'Joshua 24:5', 'Joshua', 24, 5, '&nbsp;ما بيا موسىٰ او هارون ولېږل او په مِصر باندې مې لوئ افتونه راوستل او د هغې نه پس ما تاسو راوويستلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6015, 'Joshua 24:6', 'Joshua', 24, 6, '&nbsp;ما ستاسو پلار نيکۀ د مِصر نه راوويستل او مِصريان د جنګى ګاډو او په آسونو سوارو کسانو سره په هغوئ پسې وُو. خو کله چې ستاسو پلار نيکۀ بحرِقُلزم ته ورسېدل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6016, 'Joshua 24:7', 'Joshua', 24, 7, '&nbsp;نو هغوئ ما ته د مدد دپاره فرياد وکړو او ما د هغوئ او د مِصريانو په مينځ کښې تيارۀ راوستله. ما مِصريان په سمندر لاهُو کړل او هغوئ مې ورډُوب کړل. تاسو په خپلو سترګو وليدل چې ما په مِصر څۀ کړى دى. تاسو تر ډېره وخته پورې په هغه بيابان کښې اوسېدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6017, 'Joshua 24:8', 'Joshua', 24, 8, '&nbsp;بيا ما تاسو د اموريانو مُلک ته راوستلئ، کوم چې د اُردن نمرخاتۀ طرف ته اوسېدل. هغوئ ستاسو سره جنګ وکړو، خو ما تاسو له په هغوئ باندې فتح درکړه. تاسو د هغوئ مُلک قبضه کړو او چې تاسو مخ په وړاندې تلئ نو هغوئ مو تباه کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6018, 'Joshua 24:9', 'Joshua', 24, 9, '&nbsp;بيا د موآب بادشاه صفور زوئ بلق ستاسو خِلاف جنګ وکړو. هغۀ د بعور زوئ بلعام راوغوښتو او ورته يې ووئيل چې په تاسو لعنت ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6019, 'Joshua 24:10', 'Joshua', 24, 10, '&nbsp;خو ما بلعام ته غوږ نۀ نيولو، نو ځکه هغۀ تاسو له برکت درکړو، او داسې ما تاسو د بلق نه بچ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6020, 'Joshua 24:11', 'Joshua', 24, 11, '&nbsp;تاسو د اُردن نه پورې وتئ او يريحو ته راغلئ. د يريحو سړو ستاسو خِلاف جنګ وکړو، هم هغه شان چې څنګه اموريانو، فرزيانو، کنعانيانو، حِتيانو، جرجاسيانو، حِويانو او يبوسيانو کړى وُو. خو ما تاسو له په هغه ټولو باندې فتح درکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6021, 'Joshua 24:12', 'Joshua', 24, 12, '&nbsp;چې تاسو مخ په وړاندې تلئ نو ما هغوئ د دې دپاره په وارخطايۍ آخته کړل چې هغه دوه امورى بادشاهان وشړم، دا کار ستاسو د تُورو او ليندو په ذريعه نۀ وو شوے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6022, 'Joshua 24:13', 'Joshua', 24, 13, '&nbsp;ما تاسو له يو داسې زمکه درکړه چې تاسو هيڅکله کَرلې نۀ وه او داسې ښارونه مې درکړل چې تاسو جوړ کړى نۀ وُو. اوس تاسو هلته اوسېږئ او د هغه باغونو نه انګور خورئ چې تاسو کَرلى نۀ دى او د هغه ونو نه د زيتُونو مېوه خورئ چې تاسو کَرلى نۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6023, 'Joshua 24:14', 'Joshua', 24, 14, '&nbsp;نو يشوَع فرمائيل چې، ”د مالِک خُدائ نه يرېږئ او په اخلاص او ايماندارۍ سره د هغۀ خِدمت وکړئ. او د هغه معبودانو نه ځان خلاص کړئ چې ستاسو پلار نيکۀ په مسوپتاميه او مِصر کښې د هغوئ عبادت کولو او صِرف د مالِک خُدائ خِدمت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6024, 'Joshua 24:15', 'Joshua', 24, 15, '&nbsp;کۀ ستاسو زړۀ نۀ کيږى چې د هغۀ خِدمت وکړئ، نو نن دا فېصله وکړئ چې د چا خِدمت به کوئ، د هغه معبودانو چې ستاسو پلار نيکۀ په مسوپتاميه کښې د هغوئ عبادت کولو يا د اموريانو د معبودانو، چې د چا په مُلک کښې تاسو اوس اوسېږئ. خو پاتې شوه زما او زما د خاندان خبره، نو مونږ به د مالِک خُدائ خِدمت کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6025, 'Joshua 24:16', 'Joshua', 24, 16, '&nbsp;خلقو ورته په جواب کښې ووئيل، ”مونږ به هيڅکله مالِک خُدائ نۀ پرېږدو چې د نورو معبودانو عبادت وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6026, 'Joshua 24:17', 'Joshua', 24, 17, '&nbsp;مالِک خُدائ زمونږ خُدائ پاک زمونږ پلار نيکۀ او مونږ په مِصر کښې د غلامۍ نه راوويستلو او چې هغۀ کومې معجزې کولې نو هغه مو وليدلې. چې مونږ د هر يو قوم نه هم تېرېدو او هر ځائ له هم تلو نو هغۀ مونږ په حِفاظت کښې ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6027, 'Joshua 24:18', 'Joshua', 24, 18, '&nbsp;کله چې مونږ دې مُلک ته مخ په وړاندې تلو، نو مالِک خُدائ هغه ټول اموريان وشړل کوم چې دلته اوسېدل. نو ځکه مونږ به هم د مالِک خُدائ خِدمت کوُو، هغه زمونږ خُدائ پاک دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6028, 'Joshua 24:19', 'Joshua', 24, 19, '&nbsp;يشوَع خلقو ته وفرمائيل، ”خو کېدے شى چې تاسو د دې قابل نۀ شئ چې د مالِک خُدائ خِدمت وکړئ. هغه يو مقدس او غيرتى خُدائ پاک دے او هغه به ستاسو ګناهونه نۀ معاف کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6029, 'Joshua 24:20', 'Joshua', 24, 20, '&nbsp;او کۀ تاسو هغه پرېږدئ او د پردو معبودانو خِدمت وکړئ، نو هغه به ستاسو خِلاف شى او تاسو له به سزا درکړى. هغه به تاسو تباه کړى، اګر چې هغه ستاسو سره مخکښې ښۀ هم وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6030, 'Joshua 24:21', 'Joshua', 24, 21, '&nbsp;نو خلقو يشوَع ته ووئيل، ”نه، مونږ به د مالِک خُدائ خِدمت کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6031, 'Joshua 24:22', 'Joshua', 24, 22, '&nbsp;يشوَع هغوئ ته وفرمائيل، ”تاسو په خپله د دې حقيقت ګواهان يئ چې تاسو د مالِک خُدائ خِدمت خوښ کړے دے.“ هغوئ ووئيل، ”آو، مونږ د دې خبرې ګواهان يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6032, 'Joshua 24:23', 'Joshua', 24, 23, '&nbsp;نو يشوَع ورته وفرمائيل، ”تاسو سره چې کوم پردى بُتان دى نو د هغې نه ځان خلاص کړئ، نو داسې به تاسو د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک سره وفادار اوسئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6033, 'Joshua 24:24', 'Joshua', 24, 24, '&nbsp;بيا خلقو يشوَع ته ووئيل، ”مونږ به د مالِک خُدائ د خپل خُدائ پاک خِدمت کوُو. مونږ به د هغۀ حُکمونه منو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6034, 'Joshua 24:25', 'Joshua', 24, 25, '&nbsp;نو په هغه ورځ يشوَع د خلقو سره يو لوظ وکړو او هلته په شِکم کښې هغۀ ورته قانون او اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6035, 'Joshua 24:26', 'Joshua', 24, 26, '&nbsp;يشوَع دا حُکمونه د خُدائ پاک د شريعت په کِتاب کښې وليکل. بيا هغۀ يو لوئ کاڼے واخستلو او د مالِک خُدائ په مقدس ځائ کښې يې د څېړۍ د ونې لاندې ودرولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6036, 'Joshua 24:27', 'Joshua', 24, 27, '&nbsp;هغۀ ټولو خلقو ته وفرمائيل، ”دا کاڼے به زمونږ ګواه وى. دې کاڼى هغه ټولې خبرې اورېدلې دى کومې چې مالِک خُدائ مونږ سره کړې دى. نو دا به ستاسو خِلاف يو ګواه وى، چې د خُدائ پاک خِلاف د سرکشۍ نه مو وساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6037, 'Joshua 24:28', 'Joshua', 24, 28, '&nbsp;بيا يشوَع خلق ولېږل او هغوئ ټول د هغه مُلک خپلې برخې ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6038, 'Joshua 24:29', 'Joshua', 24, 29, '&nbsp;د هغې نه پس، د مالِک خُدائ خِدمتګار د نون زوئ يشوَع د يو سل او لسو کالو په عُمر کښې وفات شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6039, 'Joshua 24:30', 'Joshua', 24, 30, '&nbsp;هغوئ هغه د اِفرائيم د غرونو په مُلک کښې د تمنت‌سِره سره په خپله زمکه کښې ښخ کړو چې دا مُلک د جعس غر شمالى طرف ته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6040, 'Joshua 24:31', 'Joshua', 24, 31, '&nbsp;ترڅو پورې چې يشوَع ژوندے وو، نو بنى اِسرائيلو د مالِک خُدائ خِدمت کولو او د هغۀ د مرګ نه پس هغوئ تر هغې پورې هم دغه شان کول چې هغه مشران ژوندى وُو چې کومو مشرانو په خپله هغه هر څۀ وليدل چې مالِک خُدائ څۀ د بنى اِسرائيلو دپاره کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6041, 'Joshua 24:32', 'Joshua', 24, 32, '&nbsp;بنى اِسرائيلو چې د مِصر نه د يوسف کوم هډُوکى راوړى وُو نو هغوئ هغه د شِکم په هغه زمکه کښې ښخ کړل کومه چې يعقوب د شِکم د پلار د همور د زامنو نه د سپينو زرو په سلو سيکو باندې اخستې وه. دا هغه زمکه وه چې د يوسف د اولاد په ذريعه ميراث شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6042, 'Joshua 24:33', 'Joshua', 24, 33, '&nbsp;د هارون زوئ اِلى‌عزر مړ شو او په جبعه کښې ښخ شو، دا هغه ښار وو چې د اِفرائيم د غرونو په مُلک کښې وو او چې د هغۀ زوئ فينحاس له ورکړے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6043, 'Judges 1:1', 'Judges', 1, 1, '&nbsp;د يشوَع د مرګ نه پس بنى اِسرائيلو د مالِک خُدائ نه تپوس وکړو، ”زمونږ کومې قبيلې وړومبے لاړې شى چې په کنعانيانو حمله وکړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6044, 'Judges 1:2', 'Judges', 1, 2, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”د يهوداه قبيله دې وړومبے لاړه شى. زۀ هغه مُلک د هغوئ په حواله کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6045, 'Judges 1:3', 'Judges', 1, 3, '&nbsp;د يهوداه خلقو د شمعون قبيلې يعنې خپلو رشته‌دارو ته ووئيل، ”مونږ سره هغه علاقې ته لاړ شئ چې مونږ له راکړے شوې ده او مونږ به په شريکه د کنعانيانو سره جنګ وکړُو. بيا به مونږ ستاسو سره هغه علاقې ته لاړ شو کومه چې تاسو له درکړے شوې ده.“ نو د شمعون قبيله', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6046, 'Judges 1:4', 'Judges', 1, 4, '&nbsp;او د يهوداه قبيله په شريکه جنګ له لاړل. مالِک خُدائ هغوئ له په کنعانيانو او فرزيانو فتح ورکړه او هغوئ د بزق په ښار کښې لسو زرو سړو له شکست ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6047, 'Judges 1:5', 'Judges', 1, 5, '&nbsp;هغوئ ادونى‌بزق هلته وموندلو او د هغۀ سره يې جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6048, 'Judges 1:6', 'Judges', 1, 6, '&nbsp;ادونى‌بزق وتښتېدو، خو هغوئ ورپسې وُو او وې نيولو او د لاسونو او پښو مټې ګوتې يې ترې نه پرې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6049, 'Judges 1:7', 'Judges', 1, 7, '&nbsp;ادونى‌بزق ووئيل، ”اويا داسې بادشاهانو زما د دسترخوان نه پاتې شوې ټُکړې راټولې کړې دى چې د هغوئ د لاسونو او د پښو غټې ګوتې پرې کړے شوې وې. اوس خُدائ پاک ما سره هم هغه شان وکړل لکه څنګه چې ما د هغوئ سره کړى وُو.“ هغه يروشلم ته بوتلے شو، چرته چې هغه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6050, 'Judges 1:8', 'Judges', 1, 8, '&nbsp;د يهوداه سړو په يروشلم حمله وکړه او قبضه يې کړو. هغوئ د دې خلق ووژل او په ښار يې اور ولګولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6051, 'Judges 1:9', 'Judges', 1, 9, '&nbsp;د دې نه پس هغوئ روان وُو چې کنعانيانو سره جنګ وکړى چې هغوئ د غرونو په مُلک، جنوبى اوچه برخه او لاندې علاقو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6052, 'Judges 1:10', 'Judges', 1, 10, '&nbsp;هغوئ د کنعانيانو خِلاف روان شول. کنعانيان د حبرون په ښار کښې اوسېدل، چې مخکښې دا د قِريَت‌اربع په نوم يادېدو او هلته هغوئ د سيسى، اخيمان او تلمى ډلو له شکست ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6053, 'Judges 1:11', 'Judges', 1, 11, '&nbsp;د يهوداه سړى د هغه ځائ نه د دبير ښار طرف ته روان شول، چې په هغه وخت کښې د قِريَت‌سِفر په نوم يادېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6054, 'Judges 1:12', 'Judges', 1, 12, '&nbsp;په هغوئ کښې د يو نوم کالب وو، کالب وفرمائيل، ”زۀ به خپله لور عکسه هغه سړى له ورکړم چې وادۀ يې کړى چې څوک قِريَت‌سِفر قبضه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6055, 'Judges 1:13', 'Judges', 1, 13, '&nbsp;هغه ښار عتنى‌اېل قبضه کړو، چې د کالب د کشر ورور قنز زوئ وو، نو کالب خپله لور عکسه هغۀ ته وادۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6056, 'Judges 1:14', 'Judges', 1, 14, '&nbsp;د وادۀ په ورځ عکسې عتنى‌اېل ته منت وکړو چې د هغې د پلار نه يو پټے وغواړى. هغه د خپل خر نه کوزه شوه او کالب ترې نه تپوس وکړو، ”تۀ څۀ غواړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6057, 'Judges 1:15', 'Judges', 1, 15, '&nbsp;هغې ورته ووئيل، ”زما سره يوه ښېګړه وکړه ځکه چې تا ما له په جنوبى برخه کښې زمکه راکړې ده، نو ما له د اوبو څۀ چينې هم راکړه.“ نو کالب هغې له بره او ښکته چينې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6058, 'Judges 1:16', 'Judges', 1, 16, '&nbsp;د موسىٰ د سخر اولاد قينيان د کجورو د ونو ښار يريحو نه د يهوداه خلقو سره روان وُو، د يهوداه صحرا ته داخل شول. هغوئ په جنوب کښې د عراد د ښار سره نزدې، خلقو سره اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6059, 'Judges 1:17', 'Judges', 1, 17, '&nbsp;د يهوداه خلق د شمعون خلقو سره لاړل او هغوئ په شريکه کنعانيانو له شکست ورکړو، کنعانيان د صِفت په ښار کښې اوسېدل. هغوئ په پوره توګه ښار تباه کړو او حُرمه نوم يې پرې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6060, 'Judges 1:18', 'Judges', 1, 18, '&nbsp;د يهوداه سړو غزه، اسقلون او عقرون، دا ټول ښارونه او د دې علاقې هم قبضه کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6061, 'Judges 1:19', 'Judges', 1, 19, '&nbsp;مالِک خُدائ د يهوداه د خلقو مل وو. هغوئ د غرونو مُلک قبضه کړو، خو هغوئ د دې جوګه نۀ وُو چې د مېدانونو نه خلق وشړى، ځکه چې د هغوئ سره د اوسپنې ګاډۍ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6062, 'Judges 1:20', 'Judges', 1, 20, '&nbsp;لکه څنګه چې موسىٰ حُکم کړے وو، حبرون کالب ته ورکړے شو، کالب د عناق د اولاد درې قبيلې د هغه ښار نه شړلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6063, 'Judges 1:21', 'Judges', 1, 21, '&nbsp;خو د بنيامين د قبيلې خلقو هغه يبوسيان ونۀ شړلے شول چې په يروشلم کښې اوسېدل او هم د هغه وخت نه يبوسيان هلته د بنيامين د خلقو سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6064, 'Judges 1:24', 'Judges', 1, 24, '&nbsp;هغوئ يو سړے وليدو چې د ښار نه راووتلو نو هغۀ ته يې ووئيل، ”ښار ته د ننوتلو لار مونږ ته وښايه او مونږ به تا سره ښۀ سلوک وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6065, 'Judges 1:25', 'Judges', 1, 25, '&nbsp;نو هغۀ ورته لار وښودله او د اِفرائيم او منسى خلقو په ښار کښې هر يو کس ووژلو او صِرف دا سړے او د هغۀ کورنۍ يې پرېښوده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6066, 'Judges 1:26', 'Judges', 1, 26, '&nbsp;وروستو دا سړے د حِتيانو مُلک ته لاړو، هلته يې يو ښار جوړ کړو او په دې باندې يې لوز نوم کېښودو، تر اوسه پورې يې هم دغه نوم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6067, 'Judges 1:27', 'Judges', 1, 27, '&nbsp;د منسى قبيلې هغه خلق ونۀ شړل چې کوم د بيت‌شان، تعنک، دور، ابليعام، مِجدو او په ګېرچاپېره کلو کښې اوسېدل، او کنعانيان هم هلته دېره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6068, 'Judges 1:28', 'Judges', 1, 28, '&nbsp;کله چې بنى اِسرائيليان طاقتور شول، نو هغوئ کنعانيان دې ته مجبور کړل چې د هغوئ دپاره کار کوى، خو بيا يې هم هغوئ ټول ونۀ شړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6069, 'Judges 1:29', 'Judges', 1, 29, '&nbsp;د اِفرائيم قبيلې هغه کنعانيان ونۀ شړل چې د جزر په ښار کښې اوسېدل، نو کنعانيان هم هلته د هغوئ سره اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6070, 'Judges 1:30', 'Judges', 1, 30, '&nbsp;د زبولون قبيلې هغه خلق ونۀ شړل کوم چې د قِطرون او نهلال په ښارونو کښې اوسېدل، نو کنعانيان هم هلته د هغوئ سره اوسېدل او دې ته مجبور وُو چې د هغوئ دپاره کار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6071, 'Judges 1:31', 'Judges', 1, 31, '&nbsp;د آشر قبيلې هغه خلق ونۀ شړل کوم چې د عکو، صيدا، احلاب، اکزيب، حلبه، افيق، رِحوب په ښارونو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6072, 'Judges 1:32', 'Judges', 1, 32, '&nbsp;د آشر قبيلې خلق د هغه ځائ د کنعانيانو سره اوسېدل، ځکه چې هغوئ کنعانيان ونۀ شړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6073, 'Judges 1:33', 'Judges', 1, 33, '&nbsp;د نفتالى قبيلې هغه خلق ونۀ شړل کوم چې د بيت‌شمس او بيت‌عنات په ښارونو کښې اوسېدل. د نفتالى خلق د هغه ځائ د کنعانيانو سره اوسېدل، خو هغوئ يې دې ته مجبور کړل چې د هغوئ دپاره کار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6074, 'Judges 1:34', 'Judges', 1, 34, '&nbsp;اموريانو د دان قبيلې خلق مجبور کړل چې د غرونو مُلک ته لاړ شى او هغوئ يې دې ته نۀ پرېښودل چې لاندې مېدان ته لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6075, 'Judges 1:35', 'Judges', 1, 35, '&nbsp;اموريان په ايالون، سعلبيم، او د حِرس په غرۀ کښې دېره وُو، خو د اِفرائيم او منسى قبيلې طاقتورې شوې او د هغوئ نه يې په زور کار اخستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6076, 'Judges 1:36', 'Judges', 1, 36, '&nbsp;د اموريانو د حد پوله د لړم درې نه واخله تر سلع پورې او د دې نه اخوا هم وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6077, 'Judges 2:1', 'Judges', 2, 1, '&nbsp;د مالِک خُدائ فرښته د جِلجال نه بوکيم ته لاړه او بنى اِسرائيلو ته يې وفرمائيل، ”ما تاسو د مِصر نه راوويستلئ او هغه مُلک ته مې راوستلئ چې ستاسو د پلار نيکۀ سره ما د هغې وعده کړې ده. ما وفرمائيل زۀ به هيڅکله ستاسو سره خپل لوظ مات نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6078, 'Judges 2:2', 'Judges', 2, 2, '&nbsp;تاسو چې د هغه خلقو سره هيڅ لوظ ونۀ کړئ کوم چې په دې مُلک کښې اوسيږى بلکې د هغوئ د قربانۍ ځايونه راوغورزوئ. خو تاسو زما د حُکم نافرمانى کړې ده. تاسو داسې ولې کړى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6079, 'Judges 2:3', 'Judges', 2, 3, '&nbsp;اوس زۀ تاسو ته وايم چې تاسو مخ په وړاندې ځئ نو زۀ به دا خلق نۀ شړم. هغوئ به ستاسو دشمنان شى او د هغوئ معبودان به ستاسو دپاره يو دام جوړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6080, 'Judges 2:4', 'Judges', 2, 4, '&nbsp;کله چې د مالِک خُدائ فرښتې دا خبرې بنى اِسرائيلو ته وکړې نو ټول قوم په چغو چغو وژړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6081, 'Judges 2:5', 'Judges', 2, 5, '&nbsp;نو ځکه په هغه ځائ يې بوکيم نوم کېښودو چې مطلب يې ژړا دے او هلته هغوئ مالِک خُدائ ته قربانۍ پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6082, 'Judges 2:6', 'Judges', 2, 6, '&nbsp;يشوَع چې کله بنى اِسرائيل رُخصت کړل، نو هره يوه قبيله لاړله چې د هغه مُلک خپله خپله برخه ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6083, 'Judges 2:7', 'Judges', 2, 7, '&nbsp;تر کومې پورې چې يشوَع ژوندے وو، نو بنى اِسرائيلو د مالِک خُدائ خِدمت کولو او د هغۀ د مرګ نه پس چې تر کومې پورې هغه مشران ژوندى وُو چې هغوئ په خپله هغه ټول لوئ کارونه ليدلى وُو چې مالِک خُدائ د بنى اِسرائيلو دپاره کړى وُو، نو هغوئ هم هغه شان کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6084, 'Judges 2:8', 'Judges', 2, 8, '&nbsp;د مالِک خُدائ خِدمت کوونکے د نون زوئ يشوَع د يو سل او لسو کالو په عُمر کښې مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6085, 'Judges 2:9', 'Judges', 2, 9, '&nbsp;هغه په خپله زمکه کښې ښخ کړے شو، هغه ځائ د جعس په شمالى طرف د اِفرائيم غرونو په مُلک تمنت‌حِرس کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6086, 'Judges 2:10', 'Judges', 2, 10, '&nbsp;هغه ټول نسل هم مړ شو او ورپسې نسل مالِک خُدائ او هغه څۀ هېر کړل چې مالِک خُدائ د بنى اِسرائيلو دپاره کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6087, 'Judges 2:11', 'Judges', 2, 11, '&nbsp;نو بنى اِسرائيلو د مالِک خُدائ خِلاف ګناه وکړه او د بعل د بُتانو عبادت يې شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6088, 'Judges 2:12', 'Judges', 2, 12, '&nbsp;هغوئ د مالِک خُدائ عبادت پرېښودو، کوم چې د هغوئ د پلار نيکۀ خُدائ پاک وو، هغه خُدائ پاک چې هغوئ يې د مِصر د مُلک نه راويستلى وُو او هغوئ د نورو معبودانو عبادت شروع کړو، د هغه خلقو د معبودانو چې د هغوئ په خواوشا کښې اوسېدل، هغوئ ورته سجدې وکړې او مالِک خُدائ يې په غصه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6089, 'Judges 2:13', 'Judges', 2, 13, '&nbsp;هغوئ د مالِک خُدائ عبادت پرېښودو او د بعل او عستارات خِدمت يې شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6090, 'Judges 2:14', 'Judges', 2, 14, '&nbsp;نو مالِک خُدائ بنى اِسرائيلو ته سخت غصه شو او هغوئ يې ډاکوانو ته حواله کړل او ډاکوانو هغوئ لوټ کړل. هغۀ په هغوئ باندې ټول د خوا او شا دشمنان غالِب کړل، نو هغوئ نور د دې جوګه نۀ وُو چې خپلو دشمنانو ته ټينګ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6091, 'Judges 2:15', 'Judges', 2, 15, '&nbsp;هر ځل چې هغوئ جنګ له تلل، نو مالِک خُدائ به د هغوئ خِلاف وو او هغوئ به يې د شکست سره مخ کول، لکه څنګه چې هغۀ فرمائيلى وُو چې هغه به هم داسې وى. هغوئ په سخت کړاؤ کښې راګېر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6092, 'Judges 2:16', 'Judges', 2, 16, '&nbsp;بيا مالِک خُدائ په بنى اِسرائيلو باندې قاضيان مقرر کړل او دې قاضيانو د ډاکوانو نه خلاص کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6093, 'Judges 2:17', 'Judges', 2, 17, '&nbsp;خو بنى اِسرائيلو خپلو قاضيانو ته غوږ ونۀ نيولو. بنى اِسرائيلو د مالِک خُدائ سره بې‌غېرتى وکړه او د نورو معبودانو عبادت يې وکړو. هغوئ زر د هغې لارې نه واوړېدل چې په کومه د هغوئ پلار نيکۀ روان وُو، چې هغوئ په فرمانبردارۍ سره د مالِک خُدائ د حُکم په مطابق روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6094, 'Judges 2:18', 'Judges', 2, 18, '&nbsp;کله هم چې مالِک خُدائ بنى اِسرائيلو له يو قاضى ورکړو، نو مالِک خُدائ به د هغه قاضى مل وو او خلق به يې د خپلو دشمنانو نه بچ کول چې تر کومې به هغه قاضى ژوندے وو. نو مالِک خُدائ به په هغوئ رحم کولو ځکه هغوئ د خپلو تکليفونو او مصيبتونو لاندې فرياد کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6095, 'Judges 2:19', 'Judges', 2, 19, '&nbsp;خو چې کله به قاضى مړ شو، نو خلق به هم هغه ناولو کارونو ته وروګرځېدل او د مخکښېنى نسل نه به يې بدتر عمل کولو. هغوئ به د نورو معبودانو خِدمت او عبادت کولو او د خپلو بدو عملونو او خپلو ضدى طريقو پرېښودو نه به يې اِنکار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6096, 'Judges 2:20', 'Judges', 2, 20, '&nbsp;نو مالِک خُدائ به بنى اِسرائيلو ته سخت په قهر شو او وبه يې فرمائيل، ”دې نسل هغه لوظ مات کړے دے چې ما يې د دوئ پلار نيکۀ له د پوره کولو حُکم ورکړے وو. ځکه چې دوئ زما نافرمانى کړې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6097, 'Judges 2:21', 'Judges', 2, 21, '&nbsp;د يشوَع د مرګ په وخت چې په هغه مُلک کښې کوم قومونه پاتې وُو نو زۀ به هغوئ نور نۀ شړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6098, 'Judges 2:22', 'Judges', 2, 22, '&nbsp;زۀ به هغوئ د دې دپاره استعمال کړم چې دا معلومه کړم چې دا بنى اِسرائيليان د خپل پلار نيکۀ په شان زما په لاره روان دى او کۀ نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6099, 'Judges 2:23', 'Judges', 2, 23, '&nbsp;نو مالِک خُدائ هغه قومونه پرېښودل چې په هغه مُلک کښې پاتې شى، هغۀ نۀ يشوَع له په هغوئ باندې فتح ورکړه او نۀ يې د يشوَع د مرګ نه پس زر هغوئ وشړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6100, 'Judges 3:1', 'Judges', 3, 1, '&nbsp;بيا مالِک خُدائ څۀ قومونه په هغه مُلک کښې د دې دپاره پرېښودل چې هغه بنى اِسرائيليان وآزمائى چې کوم د کنعان په جنګونو کښې شامل نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');